pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address actor, address newCfo) public {
        // The owner is the deployer (the test contract); any other caller must
        // be rejected by the onlyOwner guard on owner-gated functions.
        vm.assume(actor != address(this));
        vm.assume(newCfo != address(0));

        vm.prank(actor);
        bool ok;
        try c.setCaller(newCfo) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a call from a non-owner to an onlyOwner-gated function
        // always reverts in the reference contract; the buggy owner() returns
        // msg.sender so the guard trivially passes and the call succeeds.
        assertTrue(!ok);
    }
}

