pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(newOwner != address(0));
        vm.assume(caller != address(this));
        vm.assume(caller != newOwner);

        // deployer (address(this)) transfers ownership to a fuzzed new owner
        c.transferOwnership(newOwner);

        // an unrelated caller queries the public owner getter:
        // the rule is that owner() reflects the STORED owner, independent of caller
        vm.prank(caller);
        assertTrue(c.owner() == newOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this));
    }

    function testFuzz_property(address actor) public {
        // actor must be an admissible non-owner caller attempting the owner-gated renounce
        vm.assume(actor != address(this));
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));

        // A non-owner cannot renounce ownership in the reference contract.
        vm.prank(actor);
        try c.renounceOwnership() {
            // If the call unexpectedly succeeds, ownership must still resolve to the stored owner
            // for every observer.
            vm.prank(actor);
            assertTrue(c.owner() == address(this), "owner must stay stored owner");
        } catch {
            // Expected in the reference: renounce reverted, ownership unchanged.
            vm.prank(actor);
            assertTrue(c.owner() == address(this), "owner must stay stored owner");
        }
    }
}

