import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address actorA, address actorB) public {
        vm.assume(actorA != actorB);
        vm.assume(actorA != address(0));
        vm.assume(actorB != address(0));

        vm.prank(actorA);
        address ownerSeenByA = c.owner();
        vm.prank(actorB);
        address ownerSeenByB = c.owner();

        // The stored owner is caller-independent: any caller sees the same owner.
        assertTrue(ownerSeenByA == ownerSeenByB);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(this)); // exclude the current owner
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != actor);

        address oldOwner = c.owner();

        vm.prank(actor);
        try c.transferOwnership(newOwner) {
            // if it succeeded, actor must actually have been the owner
            assertTrue(false, "non-owner changed ownership");
        } catch {
            assertTrue(c.owner() == oldOwner, "owner changed");
        }
    }
}
